const express = require('express');
const app = express();
app.get('/api/users', (req, res) => res.json([{ id: 1, name: 'Ada' }]));
module.exports = { app };

function calculateShippingCost(weightKg, expedited = false) {
  if (weightKg <= 0) throw new Error('weight must be positive');
  const base = weightKg * 2.5;
  return expedited ? base * 1.5 : base;
}
module.exports = { calculateShippingCost };

